def esc(x): return html.escape(x,quote=True)
def p(x): return '<p>'+esc(x)+'</p>'
def link(text,url,cls='text-link'): return f'<a class="{cls}" href="{esc(url)}">{esc(text)}</a>'
def eyebrow(x): return '<p class="eyebrow">'+esc(x)+'</p>'
def faqs(city):
    s=refs['docs']['ug-spec' if city=='Union Grove' else 'pp-spec']
    s=s[s.index('U6 —' if city=='Union Grove' else 'M6.6 FAQ'):s.index('U7 —' if city=='Union Grove' else 'M6.7 CLOSING')]
    pattern=r'H3:\s*(.*?)\s*(?:Paragraph:|A:)\s*(.*?)(?=\s*H3:|\Z)'
    return [(q.strip(),a.strip()) for q,a in re.findall(pattern,s,re.S)]

